<!-- 报警列表，+轮播图 -->
<template>
  <div class="yldivs">
    <video ref="videoPlayers" width="100%" height="100%" v-if="src" controls autoplay muted :src="src"></video> 
  </div>
</template>

<script>
export default {
  props: ['item'],
  data() {
    return {
      form: this.item,
      src:'',
    };
  },
  methods: {
    init(e){
      this.src = e
      this.changes_v()
    },
    changes_v(){
      this.$nextTick(() => {
        const video = this.$refs.videoPlayers
        if (video) {
          video.load()
          video.play(); // 播放视频
        }
      })
    },
  },
  created() {

  },
  mounted() {
    
  },
};
</script>

<style lang="scss" scoped>
.yldivs {
  width: 100%;
  height: 100%;
}

</style>
