<!-- 报警列表，+轮播图 -->
<template>
  <div class="yldiv">
    <div class="left">
      <el-tabs v-model="activeName">
        <el-tab-pane name="first">
          <div class="search_left">
            <div class="search_form">
              <el-form label-width="24px">
                <div class="title1">视频布局</div>
                <el-form-item>
                  <el-select
                    v-model="layout"
                    filterable
                    placeholder="请选择视频布局"
                    @change="handleChangeLayout"
                    style="width: calc(100% - 12px);height: 33px;margin-top: 16px;border-radius: 4px;"
                  >
                    <el-option
                      v-for="(item, index) in layoutOptions"
                      :key="index"
                      :label="item.label"
                      :value="item.value"
                    ></el-option>
                  </el-select>
                </el-form-item>
                <br />
                <div class="title1">监控点</div>
              </el-form>
            </div>
          </div>
          <div :class="realtime ? 'search_place':'search_place2'">
            <el-input
              v-model="listchange"
              placeholder="请输入监控点"
              @input="init"
              clearable
              style="width: 100%;margin-bottom: 12px;"
            ></el-input>
            <el-menu
              ref="hkMenu"
              class="el-menu-vertical-demo"
              :default-active="activeMenuId"
            >
              <template v-for="item in HKmenu">
                <el-submenu v-if="item.children" :index="item.id + ''">
                  <template slot="title">{{ item.equipment_name }}</template>
                  <el-menu-item
                    v-for="item1 in item.children"
                    :key="item1.id"
                    :index="item1.id + ''"
                    @click="handlePlayVideo(item1)"
                    :style="{ color: item1.online == 1 ? '' : 'gray' }"
                  >
                    {{ item1.equipment_name }}
                  </el-menu-item>
                </el-submenu>
                <el-menu-item
                  v-else
                  :index="item.id + ''"
                  @click="handlePlayVideo(item)"
                  :key="item.id"
                  :style="{ color: item.online == 1 ? '' : 'gray' }"
                >
                  {{ item.equipment_name }}
                </el-menu-item>
              </template>
            </el-menu>
          </div>
        </el-tab-pane>
      </el-tabs>
    </div>

    <!-- 右侧视频区域 -->
    <div class="right">
      <!-- 1x1 -->
      <div class="div1" v-if="layout == 1">
        <div class="w-full" :class="{ active: selectedIndex === 0 }" @click="selectVideo(0)">
          <div class="video-container">
            <el-button
              v-if="spfxSrcFlv[0] && spfxSrcFlv[0].src"
              type="danger"
            />

            <videodiv
              :ref="el => { if (el) videoRefs[0] = el }"
              :item="spfxSrcFlv[0]"
              :key="`video_0_${spfxSrcFlv[0] && spfxSrcFlv[0].src || 'default'}`"
              @error="handleVideoError(0, $event)"
            />
          </div>
        </div>
      </div>

      <!-- 2x2 -->
      <div class="div2" v-if="layout == 2">
        <div
          class="w-full"
          v-for="(item, index) in spfxSrcFlv"
          :key="index"
          :class="{ active: selectedIndex === index }"
          @click="selectVideo(index)"
        >
          <div class="video-container">
            <el-button
              v-if="item.src"
              style="background: none;border: none;color: #fff;font-size: 18px;"
              icon="el-icon-close"
              size="mini"
              circle
              class="close-btn"
              @click.stop="closeSingleVideo(index)"
            />
            <videodiv
              :ref="el => { if (el) videoRefs[index] = el }"
              :item="item"
              :key="`video_${index}_${item.src}`"
              @error="handleVideoError(index, $event)"
            />
          </div>
        </div>
      </div>

      <!-- 3x3 -->
      <div class="div3" v-if="layout == 3">
        <div
          class="w-full"
          v-for="(item, index) in spfxSrcFlv"
          :key="index"
          :class="{ active: selectedIndex === index }"
          @click="selectVideo(index)"
        >
          <div class="video-container">
            <el-button
              v-if="item.src"
              style="background: none;border: none;color: #fff;font-size: 18px;"
              icon="el-icon-close"
              size="mini"
              circle
              class="close-btn"
              @click.stop="closeSingleVideo(index)"
            />
            <videodiv
              :ref="el => { if (el) videoRefs[index] = el }"
              :item="item"
              :key="`video_${index}_${item.src}`"
              @error="handleVideoError(index, $event)"
            />
          </div>
        </div>
      </div>

      <!-- 4x4 -->
      <div class="div4" v-if="layout == 4">
        <div
          class="w-full"
          v-for="(item, index) in spfxSrcFlv"
          :key="index"
          :class="{ active: selectedIndex === index }"
          @click="selectVideo(index)"
        >
          <div class="video-container">
            <el-button
              v-if="item.src"
              style="background: none;border: none;color: #fff;font-size: 18px;"
              icon="el-icon-close"
              size="mini"
              circle
              class="close-btn"
              @click.stop="closeSingleVideo(index)"
            />
            <videodiv
              :ref="el => { if (el) videoRefs[index] = el }"
              :item="item"
              :key="`video_${index}_${item.src}`"
              @error="handleVideoError(index, $event)"
            />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import videodiv from './jsyl_video.vue'
export default {
  components: { videodiv },
  data() {
    return {
      activeName: 'first',
      layout: 2,
      HKmenu: [],
      spfxSrcFlv: [],
      videoRefs: [],

      // 重连 & 异常控制
      retryCount: {},     // 每个窗口重连次数
      retryTimer: {},     // 重连定时器
      maxRetry: 5,        // 最大重连次数
      retryDelay: 2000,   // 重连间隔

      selectedIndex: 0,
      playIndex: 0,
      activeMenuId: '',

      realtime: true,
      listchange: '',
      layoutOptions: [
        { label: '1x1', value: 1 },
        { label: '2x2', value: 2 },
        { label: '3x3', value: 3 },
        { label: '4x4', value: 4 },
      ],
    }
  },
  methods: {
    handleChangeLayout() {
      // 清空所有定时器
      Object.values(this.retryTimer).forEach(t => clearTimeout(t))
      this.retryCount = {}
      this.retryTimer = {}

      const total = this.layout * this.layout
      this.spfxSrcFlv = []
      this.videoRefs = []
      for (let i = 0; i < total; i++) {
        this.spfxSrcFlv.push({ src: '', id: i })
        this.videoRefs.push(null)
      }
      this.selectedIndex = 0
      this.playIndex = 0
      this.activeMenuId = ''
    },

    selectVideo(index) {
      this.selectedIndex = index
      this.playIndex = index
    },

    handlePlayVideo(row) {
      if (!row || !row.mp4) {
        this.$message.warning('该监控点无视频地址')
        return
      }
      this.activeMenuId = row.id + ''

      const max = this.layout * this.layout
      let current = this.playIndex
      if (this.layout === 1) current = 0
      else current = current % max

      let url = row.mp4
      if (this.layout === 4) {
        if (current > 6 && current < 12) url = url.replace(':8085/', ':8086/')
        else if (current >= 12) url = url.replace(':8085/', ':8087/')
      }

      // 开始播放前清除该窗口重连状态
      this.clearVideoRetry(current)
      this.spfxSrcFlv[current].src = url

      this.$nextTick(() => {
        const player = this.videoRefs[current]
        if (player && player.init) player.init(url)
      })

      if (this.layout !== 1) this.playIndex = current + 1
    },

    // ============================
    // 视频异常 + 断流重连（核心）
    // ============================
    handleVideoError(index, err) {
      const videoItem = this.spfxSrcFlv[index]
      if (!videoItem || !videoItem.src) return

      console.warn(`视频【${index}】异常，尝试重连...`, err)

      // 重连次数控制
      this.retryCount[index] = (this.retryCount[index] || 0) + 1
      if (this.retryCount[index] > this.maxRetry) {
        console.error(`视频【${index}】重连失败，已达最大次数`)
        this.$message.warning(`视频 ${index + 1} 播放失败，请检查设备状态`)
        this.closeSingleVideo(index)
        return
      }

      // 延迟重连
      this.retryTimer[index] = setTimeout(() => {
        this.retryVideoPlay(index)
      }, this.retryDelay)
    },

    // 重试播放
    retryVideoPlay(index) {
      const videoItem = this.spfxSrcFlv[index]
      if (!videoItem || !videoItem.src) return

      const player = this.videoRefs[index]
      if (player) {
        if (player.close) player.close()
        this.$nextTick(() => {
          if (player.init) player.init(videoItem.src)
        })
      }
    },

    // 清除某个窗口的重连状态
    clearVideoRetry(index) {
      if (this.retryTimer[index]) {
        clearTimeout(this.retryTimer[index])
        delete this.retryTimer[index]
      }
      this.retryCount[index] = 0
    },

    // 关闭单个视频
    closeSingleVideo(index) {
      // 清除重连任务
      this.clearVideoRetry(index)

      if (this.spfxSrcFlv[index]) {
        this.spfxSrcFlv[index].src = ''
      }

      const player = this.videoRefs[index]
      if (player) {
        if (player.close) player.close()
        if (player.$refs && player.$refs.video) {
          const videoEl = player.$refs.video
          videoEl.pause()
          videoEl.src = ''
          videoEl.load()
          if (player.flvPlayer) {
            player.flvPlayer.destroy()
            player.flvPlayer = null
          }
        }
      }

      this.activeMenuId = ''
    },

    init() {
      this.$http
        .get(this.$url.url_5000 + '/model_view/equipment_show', {
          params: {
            equipment_name: '',
            equipment_name1: this.listchange,
            page: 1,
            per_page: 999999,
          },
        })
        .then((res) => {
          if (res.data.code === 200) {
            this.HKmenu = res.data.data_list.data
          }
        })
    },
  },
  beforeDestroy() {
    // 页面销毁清空所有定时器
    Object.values(this.retryTimer).forEach(t => clearTimeout(t))
  },
  mounted() {
    this.handleChangeLayout()
    this.init()
  },
}
</script>

